.vault-wrap { 
  width: 180px; height: 180px; background: radial-gradient(circle, #333, #111); 
  border: 10px solid #444; border-radius: 50%; position: relative; 
  display: flex; align-items: center; justify-content: center; 
  box-shadow: 0 20px 50px rgba(0,0,0,0.9), inset 0 10px 30px rgba(0,0,0,0.8); 
  cursor: pointer; transition: border-color 0.5s;
}
.vault-handle { 
  width: 100px; height: 100px; border-radius: 50%; border: 6px solid #d4af37; 
  display: flex; align-items: center; justify-content: center; position: relative; 
  transition: transform 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275), border-color 0.5s; 
}
.vault-handle::before, .vault-handle::after { 
  content: ''; position: absolute; background: #d4af37; border-radius: 5px; transition: background 0.5s;
}
.vault-handle::before { width: 140px; height: 10px; }
.vault-handle::after { width: 10px; height: 140px; }
.vault-center { 
  width: 40px; height: 40px; background: #d4af37; border-radius: 50%; z-index: 10; 
  box-shadow: 0 0 15px rgba(0,0,0,0.8); transition: background 0.5s;
}
.vault-wrap.open { border-color: #222; }
.vault-wrap.open .vault-handle { transform: rotate(135deg); border-color: #00ffcc; box-shadow: 0 0 30px rgba(0,255,204,0.5); }
.vault-wrap.open .vault-handle::before, .vault-wrap.open .vault-handle::after, .vault-wrap.open .vault-center { background: #00ffcc; }

