const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#1a1a1a;gap:30px;';

c.innerHTML = `
  <div class="vault-wrap" id="vWrap">
    <div class="vault-handle">
      <div class="vault-center"></div>
    </div>
  </div>
  <div id="vTxt" style="color:#d4af37; font-family:sans-serif; font-size:20px; font-weight:900; letter-spacing:3px; transition:color 0.5s;">RETIREMENT SECURED</div>
`;

document.getElementById('vWrap').addEventListener('click', function(){
  this.classList.toggle('open');
  const txt = document.getElementById('vTxt');
  if(this.classList.contains('open')){ 
    txt.innerText = 'WEALTH UNLOCKED'; txt.style.color = '#00ffcc'; 
  } else { 
    txt.innerText = 'RETIREMENT SECURED'; txt.style.color = '#d4af37'; 
  }
});
